"""FastAPI webhook receiver with Stripe-style signature verification.

Scheme:
  Header:  Signature: t=<unix ts>,v1=<hex hmac-sha256 of "{t}.{raw_body}">

Rejection rules (HTTP 400, JSON body {"error": {...}}):
  - missing/undecodable header            -> invalid_signature_header
  - |now - t| > tolerance_seconds (300s) -> stale_timestamp   (replay defense;
    covers both past and future timestamps beyond tolerance)
  - HMAC digest mismatch                  -> bad_signature
"""

from __future__ import annotations

import hashlib
import hmac
import time
from typing import Any, Callable

from fastapi import FastAPI, Request

SIGNATURE_HEADER = "Signature"
TOLERANCE_SECONDS = 300  # Stripe's default replay window


class SignatureError(Exception):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def parse_signature_header(value: str | None) -> tuple[int, str]:
    """Parse "t=<ts>,v1=<hex>" into (timestamp, hex_digest)."""
    if not value:
        raise SignatureError(
            "invalid_signature_header", "Missing Signature header"
        )
    parts: dict[str, str] = {}
    for chunk in value.split(","):
        chunk = chunk.strip()
        if "=" not in chunk:
            continue
        key, _, val = chunk.partition("=")
        key, val = key.strip(), val.strip()
        # Later v1 entries win; mirrors Stripe's multi-signature support.
        if key == "v1" and key in parts:
            parts[key] = val
        else:
            parts.setdefault(key, val)

    try:
        timestamp = int(parts["t"])
    except (KeyError, ValueError):
        raise SignatureError(
            "invalid_signature_header", "Signature header missing valid t="
        ) from None
    digest = parts.get("v1", "")
    if not digest:
        raise SignatureError(
            "invalid_signature_header", "Signature header missing v1= digest"
        )
    return timestamp, digest


def verify_signature(
    secret: str,
    raw_body: bytes,
    header_value: str | None,
    now: int | float | None = None,
    tolerance: int = TOLERANCE_SECONDS,
) -> None:
    """Raise SignatureError on any failure; return None when valid."""
    timestamp_str, expected_hex = parse_signature_header(header_value)

    current = int(time.time()) if now is None else int(now)
    if abs(current - timestamp_str) > tolerance:
        raise SignatureError(
            "stale_timestamp",
            f"Timestamp {timestamp_str} outside ±{tolerance}s window",
        )

    signed_payload = f"{timestamp_str}.".encode("utf-8") + raw_body
    actual = hmac.new(
        secret.encode("utf-8"), signed_payload, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(actual, expected_hex):
        raise SignatureError("bad_signature", "HMAC digest mismatch")


app = FastAPI(title="Signed webhook receiver")


@app.exception_handler(SignatureError)
async def _signature_error_handler(request: Request, exc: SignatureError):
    from fastapi.responses import JSONResponse

    return JSONResponse(
        status_code=400,
        content={"error": {"code": exc.code, "message": exc.message}},
    )


def make_webhook_router(
    secret: str,
    *,
    clock: Callable[[], int | float] | int | float | None = None,
    path: str = "/webhook",
    app: FastAPI | None = None,
    tolerance: int = TOLERANCE_SECONDS,
):
    """Attach a webhook endpoint with an injectable clock.

    `clock` may be a callable returning the current time or a fixed int/float.
    Defaults to real wall-clock time.
    """
    target_app = app if app is not None else globals()["app"]

    def get_now() -> int | float:
        if callable(clock):
            return clock()
        if clock is not None:
            return clock
        return time.time()

    @target_app.post(path)
    async def webhook(request: Request) -> dict[str, Any]:
        raw_body = await request.body()
        verify_signature(
            secret,
            raw_body,
            request.headers.get(SIGNATURE_HEADER),
            now=get_now(),
            tolerance=tolerance,
        )
        return {"received": True}

    return target_app


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="127.0.0.1", port=8000)

